python3 -c "
import json
import re

# Load all questions
all_questions = []
for i in range(1, 13):
    with open(f'/input_artifacts/part_{i:02d}.json') as f:
        data = json.load(f)
        all_questions.extend(data['records'])

# Map questions by forum and title
forum_titles = {}
for q in all_questions:
    forum = q['tag_forum']
    if forum not in forum_titles:
        forum_titles[forum] = {}
    forum_titles[forum][q['title'].lower()] = q

# Check the unresolved references
unresolved = [
    ('se_gaming_60705', \"What's the point of jungling?\"),
    ('se_gaming_61095', \"How are all diminishing returns calculated in League of Legends?\"),
    ('se_gaming_101807', \"How do I begin playing DLC?\"),
]

for qid, ref in unresolved:
    print(f\"\\n{qid} looking for: {ref}\")
    q = next((x for x in all_questions if x['id'] == qid), None)
    if q:
        forum_qs = [x for x in all_questions if x['tag_forum'] == q['tag_forum']]
        for x in forum_qs:
            if ref.lower() in x['title'].lower() or x['title'].lower() in ref.lower():
                print(f\"  Found: {x['id']} - {x['title']}\")
"

python3 -c "
import json
import re

# Load all gaming questions
with open('/input_artifacts/part_01.json') as f:
    data = json.load(f)
    gaming_qs = data['records']

# Check all zombie-related questions
print('All gaming questions with zombie in title:')
for q in gaming_qs:
    if 'zombie' in q['title'].lower():
        print(f\"\\n{q['id']}: {q['title']}\")
        if 'Possible Duplicate' in q['body']:
            matches = re.findall(r'>\s*\*\*Possible Duplicate:\*\*\s*>(.+?)(?:\n|$)', q['body'])
            for m in matches:
                print(f'  -> Ref: {m[:100]}...')

print('\\n\\nAll gaming questions with magic find in title:')
for q in gaming_qs:
    if 'magic' in q['title'].lower() or 'find' in q['title'].lower():
        if any(x in q['title'].lower() for x in ['magic', 'item', 'drop', 'loot']):
            print(f\"\\n{q['id']}: {q['title']}\")
            if 'Possible Duplicate' in q['body']:
                matches = re.findall(r'>\s*\*\*Possible Duplicate:\*\*\s*>(.+?)(?:\n|$)', q['body'])
                for m in matches:
                    print(f'  -> Ref: {m[:100]}...')
"

